import getpass
from io import BytesIO, StringIO, TextIOWrapper

def _t():
    input = StringIO('')
    try:
        getpass._raw_input(input=input)
    except EOFError:
        pass
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

